#include <iostream>
#include <vector>
using namespace std;

int main(int argc, char const *argv[]) {
    int n, x;
    cin >> n;

    vector<int> mark(101, -1);

    for (int i = 0; i < n; i++) {
        cin >> x;
        mark[x] = 0;
    }

    int ans = 0;

    for (int i = 1; i <= 100; i++) {
        if (mark[i] == 0) {
            ans++;

            for (int j = i; j <= 100; j += i) {
                if (mark[j] == 0) {
                    mark[j] = 1;
                }
            }
        }
    }

    cout << ans << endl;

    return 0;
}

